const raw = $input.first().json.output || '';

const markers = [
  '###CABECALHO###',
  '###HORMONIOS###',
  '###PEPTIDEOS###',
  '###NOVOS_TRATAMENTOS###',
  '###FRAXX_ESTETICA###',
  '###TENDENCIAS###',
  '###MERCADO###'
];

const titles = [
  String.fromCodePoint(0x1F4CB) + ' *BOLETIM MEDICO DIARIO*',
  String.fromCodePoint(0x1F9EC) + ' *HORMONIOS & TRH*',
  String.fromCodePoint(0x1F489) + ' *PEPTIDEOS TERAPEUTICOS*',
  String.fromCodePoint(0x1F52C) + ' *NOVOS TRATAMENTOS*',
  String.fromCodePoint(0x26A1) + ' *FRAXX & ESTETICA*',
  String.fromCodePoint(0x1F30D) + ' *TENDENCIAS MEDICAS*',
  String.fromCodePoint(0x1F4CA) + ' *MERCADO & OPORTUNIDADES*'
];

const sep = '\u2501'.repeat(20);
const result = [];

for (let i = 0; i < markers.length; i++) {
  const start = raw.indexOf(markers[i]);
  if (start === -1) continue;
  const cStart = start + markers[i].length;
  let cEnd = raw.length;
  for (let j = i + 1; j < markers.length; j++) {
    const nx = raw.indexOf(markers[j]);
    if (nx !== -1) { cEnd = nx; break; }
  }
  let content = raw.substring(cStart, cEnd).trim();
  if (!content) continue;
  content = content.replace(/###[A-Z_]+###/g, '').trim();

  let msg = '';
  const cal = String.fromCodePoint(0x1F4C5);
  const pin = String.fromCodePoint(0x1F4CC);
  const check = String.fromCodePoint(0x2705);
  const bulb = String.fromCodePoint(0x1F4A1);
  const bell = String.fromCodePoint(0x1F514);

  if (i === 0) {
    const d = new Date();
    const data = d.toLocaleDateString('pt-BR', {weekday:'long', day:'2-digit', month:'2-digit', year:'numeric'});
    msg = titles[i] + '\n' + cal + ' ' + data + '\n' + sep + '\n\n' + content + '\n\n' + pin + ' _6 topicos especializados a seguir_';
  } else if (i === markers.length - 1) {
    msg = titles[i] + '\n' + sep + '\n\n' + content + '\n\n' + sep + '\n' + check + ' _Fim do boletim de hoje_\n' + bulb + ' _Conteudo gerado por IA com fontes verificadas_\n' + bell + ' _Proximo boletim amanha as 7h_';
  } else {
    msg = titles[i] + '\n' + sep + '\n\n' + content;
  }
  result.push({ json: { message: msg, topicIndex: i } });
}

if (result.length === 0) {
  result.push({ json: { message: titles[0] + '\n' + sep + '\n\n' + raw.substring(0, 3500), topicIndex: 0 } });
}

return result;

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentNews) {
  staticData.sentNews = [];
}
const now = Date.now();
const limit = 14 * 24 * 60 * 60 * 1000;
staticData.sentNews = staticData.sentNews.filter(e => (now - e.ts) < limit);
const titles = staticData.sentNews.map(e => e.t);
const prev = titles.join('\n- ');
return [{
  json: {
    previousTitles: titles.length > 0 ? prev : '',
    hasHistory: titles.length > 0,
    count: titles.length
  }
}];

const staticData = $getWorkflowStaticData('global');
const output = $input.first().json.output || '';
if (!staticData.sentNews) {
  staticData.sentNews = [];
}
const skip = ['BOLETIM','HORMONIOS','PEPTIDEOS','TENDENCIAS','MERCADO','FRAXX','NOVOS TRATAMENTOS','DIARIO','TRH','ESTETICA','OPORTUNIDADES','MEDICAS','TERAPEUTICOS','CABECALHO'];
const re = /\*([^*]{15,120})\*/g;
let m;
const newTitles = [];
while ((m = re.exec(output)) !== null) {
  const t = m[1].trim();
  if (t.length > 15 && !skip.some(s => t.toUpperCase().includes(s))) {
    newTitles.push(t);
  }
}
const now = Date.now();
for (const t of newTitles) {
  if (!staticData.sentNews.some(e => e.t === t)) {
    staticData.sentNews.push({ t: t, ts: now });
  }
}
const limit = 14 * 24 * 60 * 60 * 1000;
staticData.sentNews = staticData.sentNews.filter(e => (now - e.ts) < limit);
return [{ json: { output: output, savedTitles: newTitles.length } }];

